def _unpack():
    k = hashlib.sha256(_SIG.encode("utf-8")).digest()
    enc = base64.b85decode(_PROTECTED_PAYLOAD.encode("ascii"))
    ks = bytearray()
    c = 0
    while len(ks) < len(enc):
        ks.extend(hashlib.sha256(k + c.to_bytes(4, "big")).digest())
        c += 1
    dec = bytes(b ^ x for b, x in zip(enc, ks[:len(enc)]))
    return zlib.decompress(dec).decode("utf-8")

exec(compile(_unpack(), __file__, "exec"), globals())
